response.output:
{
  "world_id": "wld_veilwater",
  "name": "The Veilwater Isles",
  "description": "Across the Veilwater Isles, mountain ridges sink into cloud and salt marshes open like pale mirrors at dawn. Crane rookeries crown the reeds, their calls carrying between rival sword sects whose old claims divide the island clans. A disowned student bears her late master's tally-stick from one sect to the next, seeking a peace moot before feud and fire empty the nesting grounds. Here, a blade is not merely a weapon: its measured forms are vows made visible, and even an enemy must be met in the open. The islands' most unusual inheritance is the Mist Ledger, a tideworn register whose ink appears only when its keepers speak a truth that costs them something.",
  "locations": [
    {
      "id": "loc_mistledger_hall",
      "name": "Hall of the Mist Ledger",
      "description": "A cedar hall on stilts above a tidal inlet, where the tally-stick was carved and the old register is kept. Its ink emerges at low tide, recording not victories but debts willingly acknowledged."
    },
    {
      "id": "loc_reedglass_marsh",
      "name": "Reedglass Marsh",
      "description": "A broad, shining wetland whose reed islands shelter the last great crane rookeries. Clan wardens leave the nesting pools undisturbed, though smoke from their quarrels has begun to drift over the eggs."
    },
    {
      "id": "loc_swordpine_ridge",
      "name": "Swordpine Ridge",
      "description": "A narrow spine of black pines above the cloudline, home to a school that teaches balance on swaying branches. Its students claim the ridge's wind can expose a false stance before a blade is drawn."
    },
    {
      "id": "loc_bellmouth_harbor",
      "name": "Bellmouth Harbor",
      "description": "A crescent port built around a sea cave that tolls with each turning tide. Delegates once gathered here to swear the first moot, and its old stone ring remains neutral ground for formal challenges."
    }
  ],
  "factions": [
    {
      "id": "fac_white_reed",
      "name": "White Reed Sect",
      "description": "Marsh guardians and patient spear-and-sword practitioners who regard the crane's stillness as the highest form. They want the rookeries protected first, but fear that yielding territory will invite further claims.",
      "location_ids": [
        "loc_reedglass_marsh"
      ]
    },
    {
      "id": "fac_swordpine",
      "name": "Swordpine School",
      "description": "Austere ridge fighters who prize exact forms and public accountability. They cast out the late master's student after she refused to name a victor in a disputed lesson, yet still respect the tally-stick's authority.",
      "location_ids": [
        "loc_swordpine_ridge"
      ]
    },
    {
      "id": "fac_tidebell",
      "name": "Tidebell Compact",
      "description": "Harbor clans and ferrymen who control passage between the islands. They favor a moot that preserves trade, but their elders have quietly profited from keeping the sects divided.",
      "location_ids": [
        "loc_bellmouth_harbor"
      ]
    },
    {
      "id": "fac_ledgerward",
      "name": "Keepers of the Ledger",
      "description": "A small fellowship entrusted with the Mist Ledger and its tally-sticks. They insist each claim be spoken aloud before witnesses, and know that the late master recorded a debt no faction wants named.",
      "location_ids": [
        "loc_mistledger_hall",
        "loc_bellmouth_harbor"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_open_challenge",
      "statement": "A duel is settled by a formal challenge in witnessed ground; ambush cannot settle a claim or earn its victor standing.",
      "category": "social"
    },
    {
      "id": "rul_ledger_truth",
      "statement": "The Mist Ledger reveals its writing only at low tide and only when a keeper admits a truth that carries a personal cost.",
      "category": "metaphysics"
    },
    {
      "id": "rul_rookery_silence",
      "statement": "During nesting season, no sect may cut reeds or draw steel inside a marked crane rookery without forfeiting its claim before the moot.",
      "category": "social"
    },
    {
      "id": "rul_sword_vow",
      "statement": "A sword form taught before witnesses binds its teacher to answer a student's formal challenge in the same form.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_moot",
      "name": "The Bellmouth Accord",
      "description": "After a season of island raids, three elders met in the harbor ring and agreed that disputes between sects must be carried into the open rather than answered in secret.",
      "era": "Founding era",
      "location_ids": [
        "loc_bellmouth_harbor"
      ]
    },
    {
      "id": "evt_ledger_carving",
      "name": "The Tally of Salt and Reed",
      "description": "The first Ledger keeper carved a tally-stick from storm-felled cedar and recorded the shared boundary of the marsh. Each notch marked a promise to leave a nesting pool untouched.",
      "era": "Founding era",
      "location_ids": [
        "loc_mistledger_hall",
        "loc_reedglass_marsh"
      ]
    },
    {
      "id": "evt_student_exile",
      "name": "The Unnamed Lesson",
      "description": "A gifted student refused to declare a winner after a training bout ended in injury. Her master defended her judgment, but the school cast her out; years later, he placed the moot tally in her hands.",
      "era": "Recent years",
      "location_ids": [
        "loc_swordpine_ridge",
        "loc_mistledger_hall"
      ]
    },
    {
