response.output:
{
  "world_id": "wld_sunside_mercury_yard",
  "name": "Sunside",
  "description": "Inside Mercury's orbit, the Kestrel Array is a solar-sail shipyard built from trusswork, pressure drums, and repurposed cargo hulls. Its workers live by shift clocks, radiation forecasts, and the long arithmetic of orbital transfers. Salvage rigger Mara Venn finds a supposedly scrapped hull still drawing power through a buried yard circuit. With charter auditors due before the next scheduled transfer window, she must establish what the current means, who kept it flowing, and whether the yard's records were altered to hide a dangerous claim. The setting is hard science fiction: distances impose delays, sunlight is both resource and hazard, and no ship or message outruns light. Beneath the yard's practical routines lies a distinctive custom: every dismantled hull leaves behind a public ledger of its last measured power draw, a record workers call its afterglow.",
  "locations": [
    {
      "id": "loc_kestrel_frame",
      "name": "Kestrel Array",
      "description": "The main yard, a rotating cluster of hab drums, machine trusses, and docking spars in a heliocentric orbit inside Mercury's. Ships arrive and depart on calculated windows; the yard itself cannot simply move out of danger."
    },
    {
      "id": "loc_sunside_slip",
      "name": "Sunside Slip",
      "description": "An exposed assembly berth where crews unfurl and tension sail membranes under harsh sunlight. Reflective screens and timed work rotations limit heat load, while small errors in rigging can twist a departing craft off its planned trajectory."
    },
    {
      "id": "loc_cold_stack",
      "name": "Cold Stack",
      "description": "A shadowed rack of tagged wreck sections and sealed power trunks awaiting inspection or disposal. The hull listed as scrapped rests here, its exterior dark but a faint, intermittent current still registering in the stack's isolated bus."
    },
    {
      "id": "loc_charter_archive",
      "name": "Charter Archive",
      "description": "A shielded records vault attached to the yard's administrative drum. It holds inspection logs, salvage claims, and the afterglow ledger; access is logged, and older paper-backed sensor strips can contradict the polished database."
    }
  ],
  "factions": [
    {
      "id": "fac_yardwright_union",
      "name": "Yardwright Compact",
      "description": "The riggers, welders, and habitat technicians who keep the Kestrel Array working. They defend the afterglow ledger as a worker-owned record and fear that a formal inquiry will freeze jobs and docking rights.",
      "location_ids": [
        "loc_kestrel_frame",
        "loc_sunside_slip",
        "loc_cold_stack"
      ]
    },
    {
      "id": "fac_charter_office",
      "name": "Helion Charter Office",
      "description": "The distant authority that licenses the yard, approves salvage transfers, and sends auditors on scheduled routes. Its officials rely on the yard's records, but a disputed hull could expose the office to liability for certifying a false disposal.",
      "location_ids": [
        "loc_charter_archive",
        "loc_kestrel_frame"
      ]
    },
    {
      "id": "fac_lumen_recovery",
      "name": "Lumen Recovery",
      "description": "A lean salvage contractor with a claim to the Kestrel Array's most valuable dismantling work. It wants the Cold Stack cleared before the audit and argues that unverified power readings are not proof of an active asset.",
      "location_ids": [
        "loc_cold_stack",
        "loc_sunside_slip"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_light_delay",
      "statement": "No ship or signal exceeds the speed of light; messages between the yard and distant authorities arrive only after measurable delay.",
      "category": "physics"
    },
    {
      "id": "rul_orbital_transfers",
      "statement": "Travel between heliocentric orbits requires planned burns, transfer windows, and propellant; a sail can alter a trajectory gradually but cannot provide instant arrival.",
      "category": "physics"
    },
    {
      "id": "rul_sail_pressure",
      "statement": "A solar sail gains momentum from sunlight, and its thrust depends on illumination, orientation, and membrane condition.",
      "category": "technology"
    },
    {
      "id": "rul_power_trace",
      "statement": "Every energized yard circuit leaves a measurable load in its local bus records, though a damaged or deliberately rerouted line can obscure the source.",
      "category": "technology"
    },
    {
      "id": "rul_afterglow",
      "statement": "By Compact custom, the final verified power draw of a dismantled hull is entered in a public afterglow ledger, preserving a trace workers can compare against later readings.",
      "category": "social"
    },
    {
      "id": "rul_exposure",
      "statement": "Radiation and heat exposure accumulate during exterior work; shielding, task duration, and forecast discipline determine safe crew limits.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_array_foundation",
      "name": "The First Truss",
      "description": "The Kestrel Array began as a modest orbital repair platform assembled from cargo modules and salvaged beams. Its founders chose a stable working orbit over a surface base, trading easy access to raw material for predictable routes and flexible docking.",
      "era": "Founding years",
      "location_ids": [
        "loc_kestrel_frame"
      ]
    },
    {
      "id": "evt_ledger_custom",
      "name": "The Afterglow Compact",
      "description": "After a rushed disposal erased evidence of a still-live power trunk, yard crews demanded a shared record of each hull's last measured draw. The custom became part of the Compact's working agreement and later a key part of the yard's charter audits.",
      "era": "Compact formation",
      "location_ids": [
        "loc_cold_stack",
        "loc_charter_archive"
      ]
    },
    {
      "id": "evt_hull_scrapped",
      "name": "Disposition of the Asterion",
      "description": "The Asterion was marked scrapped after a failed inspection and moved to the Cold Stack. Its disposal entry records a zeroed bus, but a maintenance strip archived separately shows a small, recurring load on the same circuit.",
      "era": "Recent cycle",
      "location_ids": [
        "loc_cold_stack",
        "loc_charter_archive"
      ]
    },
    {
      "id": "evt_audit_notice",
      "name": "Notice of Review",
      "description": "The Charter Office scheduled an audit for the next available transfer window. Lumen Recovery began clearing contested sections, while Yardwright technicians noticed that the Asterion's isolated bus continued to draw current.",
      "era": "Current cycle",
      "location_ids": [
        "loc_kestrel_frame",
        "loc_cold_stack",
        "loc_charter_archive"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_scrap_record",
      "name": "The Live Hull Dispute",
      "description": "The Yardwright Compact wants the persistent draw investigated before the hull is dismantled; Lumen Recovery wants the stack cleared under its salvage claim. The Charter Office's approaching audit could validate the workers' evidence or freeze the yard's operations.",
      "faction_ids": [
        "fac_yardwright_union",
        "fac_lumen_recovery",
        "fac_charter_office"
      ]
    },
    {
      "id": "cnf_ledger_access",
      "name": "Who Controls the Record",
      "description": "The afterglow ledger is publicly trusted, but its source strips are kept in a controlled archive. Workers suspect the disposal entry was altered; officials insist that an unbroken audit trail matters more than a suspicious sensor reading.",
      "faction_ids": [
        "fac_yardwright_union",
        "fac_charter_office"
      ]
    }
  ]
}

