response.output:
{
  "world_id": "wld_rainward_vales",
  "name": "The Rainward Vales",
  "description": "In a post-apocalyptic basin where old roads have softened into fields and the hills still shed the memory of vanished storms, a seed-keeper's caravan must cross three recovering valley towns before the last frost. Grain stock is both food and promise: every handful traded can mend a route or deepen the feud that divided the seedway. The fourth stop, a weathered wayhouse between the towns, holds the only surviving map of the old planting paths. Nothing powered remains; people travel by foot, mule, and hand-built cart, carrying salvaged tools and hard-won patience. The valleys are poor, wary, and quietly inventive. Hope survives in shared harvests, in rain marks cut into doorposts, and in seeds whose flowers remember the color of a lost spring.",
  "locations": [
    {
      "id": "loc_brackenford",
      "name": "Brackenford",
      "description": "A riverside town of reed roofs and hand-dug irrigation ditches, recovering from two failed harvests. Its council will trade grain stock for seed, but insists the caravan first repair a washed-out footbridge."
    },
    {
      "id": "loc_ashcombe",
      "name": "Ashcombe",
      "description": "A settlement built among the charcoal-dark foundations of an old mill. Its growers keep a strict communal ledger, and distrust anyone carrying grain without a witness to its measure."
    },
    {
      "id": "loc_morrowfield",
      "name": "Morrowfield",
      "description": "A terraced town above a cold spring, where children tend small plots between stone walls. Its people preserve a rare seed strain that sprouts after a light frost, but the spring channel is silted and contested."
    },
    {
      "id": "loc_rainmark_house",
      "name": "Rainmark House",
      "description": "A roofless wayhouse at the fork between the towns, its lintels scored with generations of rainfall tallies. Beneath a loose flagstone lies the old seedway map, marked with route agreements that neither side of the feud now trusts."
    }
  ],
  "factions": [
    {
      "id": "fac_waykeepers",
      "name": "The Waykeepers",
      "description": "Seed-keepers, mule drivers, and repairers who carry small stores between settlements. They record each trade on paired wooden tallies so neither party can quietly alter a debt.",
      "location_ids": [
        "loc_brackenford",
        "loc_ashcombe",
        "loc_morrowfield",
        "loc_rainmark_house"
      ]
    },
    {
      "id": "fac_riverwardens",
      "name": "The Riverwardens",
      "description": "Brackenford's ditch tenders and bridge-menders, who believe the old seedway gave Ashcombe first claim on water and grain. They will reopen the bridge only if the route compact is renegotiated.",
      "location_ids": [
        "loc_brackenford",
        "loc_rainmark_house"
      ]
    },
    {
      "id": "fac_ash_council",
      "name": "The Ash Council",
      "description": "Ashcombe's growers and ledger-keepers, bound by a famine-era pledge never to surrender grain without a witnessed measure. They fear a new compact will erase what their town sacrificed to survive.",
      "location_ids": [
        "loc_ashcombe",
        "loc_rainmark_house"
      ]
    },
    {
      "id": "fac_springward",
      "name": "The Springward",
      "description": "Morrowfield's spring tenders, who guard the frost-tolerant seed and the channel that sustains it. They will share both only if upstream towns agree to keep the water clear.",
      "location_ids": [
        "loc_morrowfield"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_no_power",
      "statement": "No powered machinery remains usable; work, travel, and craft depend on hands, animals, wind, and flowing water.",
      "category": "technology"
    },
    {
      "id": "rul_seed_kept",
      "statement": "A seed saved for planting is not counted as ordinary food unless its keeper freely releases it.",
      "category": "social"
    },
    {
      "id": "rul_tally_witness",
      "statement": "A grain trade is binding only when both parties mark matching wooden tallies in the presence of a witness.",
      "category": "social"
    },
    {
      "id": "rul_water_runs_down",
      "statement": "Spring water follows the valley channels downhill, so an upstream blockage can starve every lower terrace.",
      "category": "physics"
    },
    {
      "id": "rul_rain_marks",
      "statement": "At Rainmark House, a fresh rain line on the lintel is treated as a public warning that the next frost may arrive early.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_seedway_compact",
      "name": "The First Seedway Compact",
      "description": "After the old order failed, the towns agreed to share planting seed and keep a common route through Rainmark House. The compact made small harvests possible across the basin.",
      "era": "Early Recovery",
      "location_ids": [
        "loc_rainmark_house",
        "loc_brackenford",
        "loc_ashcombe",
        "loc_morrowfield"
      ]
    },
    {
      "id": "evt_broken_ditch",
      "name": "The Broken Ditch",
      "description": "A flood tore through Brackenford's upper ditch. Ashcombe diverted stored grain to keep its own growers alive, while Brackenford says that grain had been promised for repairs. Their rival accounts split the seedway routes.",
      "era": "The Lean Years",
      "location_ids": [
        "loc_brackenford",
        "loc_ashcombe"
      ]
    },
    {
      "id": "evt_spring_seed_saved",
      "name": "The Spring Seed Saved",
      "description": "Morrowfield's tenders selected a seed strain that survives a brief frost and planted it above the cold spring. They kept it out of the feud, but now its limited stores could protect all three towns if the channel is restored.",
      "era": "Two Harvests Ago",
      "location_ids": [
        "loc_morrowfield"
      ]
    },
    {
      "id": "evt_map_uncovered",
      "name": "The Map Beneath the Stone",
      "description": "A child sheltering at Rainmark House found the route map beneath a loose flagstone. Its faded marks show that the compact promised shared water repairs before grain repayment, a detail missing from both towns' ledgers.",
      "era": "This Thaw",
      "location_ids": [
        "loc_rainmark_house"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_grain_and_repair",
      "name": "Grain Before the Frost",
      "description": "Brackenford needs grain stock and a repaired bridge; Ashcombe will not release grain until old debts are settled. The caravan has little time to prove the map's account and persuade both towns to honor a shared obligation.",
      "faction_ids": [
        "fac_waykeepers",
        "fac_riverwardens",
        "fac_ash_council"
      ]
    },
    {
      "id": "cnf_spring_channel",
      "name": "The Silted Spring",
      "description": "Morrowfield's rare seed could rescue the next planting, but its channel is clogged and its tenders refuse to share while upstream disputes threaten the water. Clearing it requires labor from towns that do not trust one another.",
      "faction_ids": [
        "fac_waykeepers",
        "fac_riverwardens",
        "fac_ash_council",
        "fac_springward"
      ]
    }
  ]
}

