      "name": "The Ash Council",
      "description": "Ashcombe's growers and ledger-keepers, bound by a famine-era pledge never to surrender grain without a witnessed measure. They fear a new compact will erase what their town sacrificed to survive.",
      "location_ids": [
        "loc_ashcombe",
        "loc_rainmark_house"
      ]
    },
    {
      "id": "fac_springward",
      "name": "The Springward",
      "description": "Morrowfield's spring tenders, who guard the frost-tolerant seed and the channel that sustains it. They will share both only if upstream towns agree to keep the water clear.",
      "location_ids": [
        "loc_morrowfield"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_no_power",
      "statement": "No powered machinery remains usable; work, travel, and craft depend on hands, animals, wind, and flowing water.",
      "category": "technology"
    },
    {
      "id": "rul_seed_kept",
      "statement": "A seed saved for planting is not counted as ordinary food unless its keeper freely releases it.",
      "category": "social"
    },
    {
      "id": "rul_tally_witness",
      "statement": "A grain trade is binding only when both parties mark matching wooden tallies in the presence of a witness.",
      "category": "social"
    },
    {
      "id": "rul_water_runs_down",
      "statement": "Spring water follows the valley channels downhill, so an upstream blockage can starve every lower terrace.",
      "category": "physics"
    },
    {
      "id": "rul_rain_marks",
      "statement": "At Rainmark House, a fresh rain line on the lintel is treated as a public warning that the next frost may arrive early.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_seedway_compact",
      "name": "The First Seedway Compact",
      "description": "After the old order failed, the towns agreed to share planting seed and keep a common route through Rainmark House. The compact made small harvests possible across the basin.",
      "era": "Early Recovery",
      "location_ids": [
        "loc_rainmark_house",
        "loc_brackenford",
        "loc_ashcombe",
        "loc_morrowfield"
      ]
    },
    {
      "id": "evt_broken_ditch",
      "name": "The Broken Ditch",
      "description": "A flood tore through Brackenford's upper ditch. Ashcombe diverted stored grain to keep its own growers alive, while Brackenford says that grain had been promised for repairs. Their rival accounts split the seedway routes.",
      "era": "The Lean Years",
      "location_ids": [
        "loc_brackenford",
        "loc_ashcombe"
      ]
    },
    {
      "id": "evt_spring_seed_saved",
      "name": "The Spring Seed Saved",
      "description": "Morrowfield's tenders selected a seed strain that survives a brief frost and planted it above the cold spring. They kept it out of the feud, but now its limited stores could protect all three towns if the channel is restored.",
      "era": "Two Harvests Ago",
      "location_ids": [
        "loc_morrowfield"
      ]
    },
    {
      "id": "evt_map_uncovered",
      "name": "The Map Beneath the Stone",
      "description": "A child sheltering at Rainmark House found the route map beneath a loose flagstone. Its faded marks show that the compact promised shared water repairs before grain repayment, a detail missing from both towns' ledgers.",
      "era": "This Thaw",
      "location_ids": [
        "loc_rainmark_house"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_grain_and_repair",
      "name": "Grain Before the Frost",
      "description": "Brackenford needs grain stock and a repaired bridge; Ashcombe will not release grain until old debts are settled. The caravan has little time to prove the map's account and persuade both towns to honor a shared obligation.",
      "faction_ids": [
        "fac_waykeepers",
        "fac_riverwardens",
        "fac_ash_council"
      ]
    },
    {
      "id": "cnf_spring_channel",
      "name": "The Silted Spring",
      "description": "Morrowfield's rare seed could rescue the next planting, but its channel is clogged and its tenders refuse to share while upstream disputes threaten the water. Clearing it requires labor from towns that do not trust one another.",
      "faction_ids": [
        "fac_waykeepers",
        "fac_riverwardens",
        "fac_ash_council",
        "fac_springward"
      ]
    }
  ]
}

response.output:
{
  "world_id": "wld_ashen_measure",
  "name": "The Ashen Measure",
  "description": "Beyond the last breath lies a country of counting-houses built along a black river, where every soul arrives as a line of ink awaiting its final weight. The courts of the dead are orderly in the way only an immortal bureaucracy can be: forms are copied, seals are argued over, and no one can explain why the queue moves faster on Thursdays. A junior scribe discovers a mortal soul entered under the wrong ledger column. Correcting the mark means carrying it upward through offices whose clerks would rather preserve a tidy error than answer for a messy truth. Here, lives have ended, but their accounts still change—and the difference can decide what a soul must carry beyond the courts.",
  "locations": [
    {
      "id": "loc_black_quay",
      "name": "Black Quay",
      "description": "A landing of smooth basalt where newly arrived souls step ashore carrying the last sound they remember. Ferrymen issue numbered clay slips and insist that lost slips are a personal failing."
    },
    {
      "id": "loc_intake_hall",
      "name": "Hall of First Entries",
      "description": "A vast intake room where clerks record each soul's name, final breath, and unresolved obligations. Its ceiling is tiled with old tally marks that rearrange themselves when a case is misfiled."
    },
    {
      "id": "loc_tilted_archive",
      "name": "The Tilted Archive",
      "description": "A leaning stack of narrow rooms where unfinished accounts are stored in drawers that slide toward whoever owes the most. A misclassified soul's file can be found here by following the dust uphill."
    },
    {
      "id": "loc_weight_court",
      "name": "Court of the Quiet Scale",
      "description": "A circular chamber with a single balance whose pans measure obligations rather than virtue. Its judges hear evidence in whispers, since loud claims are considered a form of excess."
    },
    {
      "id": "loc_upper_countinghouse",
      "name": "The Upper Counting-House",
      "description": "The highest office above the black river, where senior auditors decide which accounts may be amended. Its windows show no sky, only the ink-dark water and every reflection it has ever kept."
    }
  ],
  "factions": [
    {
      "id": "fac_first_marks",
      "name": "The First Marks",
      "description": "Junior scribes who enter new arrivals into the ledger and know that a misplaced column can outlast its author. They trade penciled corrections in the margins, officially for practice.",
      "location_ids": [
        "loc_intake_hall",
        "loc_tilted_archive"
      ]
    },
    {
      "id": "fac_sealed_measure",
      "name": "Keepers of the Sealed Measure",
      "description": "Judges and auditors sworn to preserve the authority of the final tally. Some believe an amended account weakens every verdict; others fear what a truly accurate measure might reveal.",
      "location_ids": [
        "loc_weight_court",
        "loc_upper_countinghouse"
      ]
    },
    {
      "id": "fac_quay_compters",
      "name": "Quay Compters",
      "description": "Ferrymen and slip-keepers who track arrivals before the courts claim them. Their unofficial records are scrupulous, though their fees are not.",
      "location_ids": [
        "loc_black_quay",
        "loc_intake_hall"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_ended_breath",
      "statement": "A soul whose mortal life has ended cannot resume it; only its account can move between columns, offices, and judgments.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ink_records",
      "statement": "Every soul must be entered in the ledger before it can be weighed, and an unrecorded name cannot be called in court.",
      "category": "social"
    },
    {
      "id": "rul_weight_debt",
      "statement": "The Quiet Scale measures obligations and their consequences, not goodness, rank, or the volume of a soul's protests.",
      "category": "metaphysics"
    },
    {
      "id": "rul_correction_witness",
      "statement": "An account may be amended only when its original mark and one independent witness are presented together.",
      "category": "social"
    },
    {
      "id": "rul_river_memory",
      "statement": "The black river keeps the reflections of every soul that has crossed it, but its reflections cannot testify without a living clerk to interpret them.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_first_tally",
      "name": "The First Tally",
      "description": "When the courts were founded, their first clerks used a single column for every obligation. The resulting queue lasted an age, and the column was divided into many smaller ones.",
      "era": "Founding of the Courts",
      "location_ids": [
        "loc_intake_hall",
        "loc_upper_countinghouse"
      ]
    },
    {
      "id": "evt_quay_slips",
      "name": "The Clay Slip Accord",
      "description": "After a ferry manifest vanished into the river, the Quay Compters won the right to keep a duplicate record outside the courts' control.",
      "era": "Age of the River Bargain",
      "location_ids": [
        "loc_black_quay",
        "loc_intake_hall"
      ]
    },
    {
      "id": "evt_still_balance",
      "name": "The Still Balance",
      "description": "A judge once tried to weigh an entire archive at once. The scale did not move for seven days, and the court decreed that every account must be heard alone.",
      "era": "The Long Hearing",
      "location_ids": [
        "loc_tilted_archive",
        "loc_weight_court"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_column_error",
      "name": "The Wrong Column",
      "description": "A soul is due before the Quiet Scale with an obligation entered under another person's name. The First Marks want the entry corrected before judgment; the Keepers of the Sealed Measure fear that admitting the error will reopen a chain of settled accounts.",
      "faction_ids": [
        "fac_first_marks",
        "fac_sealed_measure"
      ]
    },
    {
      "id": "cnf_duplicate_manifest",
      "name": "Two Records, One Arrival",
      "description": "The Quay Compters' private manifest contradicts the court's official ledger. The duplicate could prove the clerical error, but revealing it would expose how many past verdicts relied on the same disputed method.",
      "faction_ids": [
        "fac_quay_compters",
        "fac_sealed_measure"
      ]
    }
  ]
}

