response.output:
{
  "world_id": "wld_mourning_reach",
  "name": "Mourning Reach",
  "description": "Mourning Reach is a low, gaslit city spread across the mudflats and drowned foundations of an estuary. Its narrow lanes vanish into fog, and the tide rearranges the edges of familiar streets. Lamps burn town gas or oil; gears, weights, and ropes drive the city's machines. Bells govern the hours, warn of shoals, and summon parish watchmen. The great storm-bells ring from towers above the harbor, though no living founder admits to having cast their newest pattern. An apprentice hears it first. The parish orders every bell silenced before the next fog, but the sound seems to travel through stone and water as readily as through air.",
  "locations": [
    {
      "id": "loc_bellfoundry",
      "name": "The Ninefold Foundry",
      "description": "A soot-dark workshop where bells are cast in clay molds and cooled in brackish water. Nine empty hooks hang above the apprentice benches, though the master insists the shop has always had only eight."
    },
    {
      "id": "loc_parish_tower",
      "name": "Saint Orra's Tower",
      "description": "The parish's tallest stone tower, its storm-bells lashed against salt winds. A narrow stair ends at a sealed chamber whose door grows damp whenever the bells ring."
    },
    {
      "id": "loc_drowned_market",
      "name": "The Sunken Exchange",
      "description": "A market of raised planks and shuttered stalls built over a quarter swallowed by the estuary. Bargainers leave coins in little oilskin cups when the lower bells sound."
    },
    {
      "id": "loc_tide_archive",
      "name": "The Silt Archive",
      "description": "A record house on timber piles, where clerks preserve deeds on waxed linen and mark each flood line on its central pillar. The oldest ledgers describe a bell tower absent from every map."
    },
    {
      "id": "loc_lantern_quay",
      "name": "Lantern Quay",
      "description": "A crescent of mooring posts and gas lamps at the harbor mouth. In heavy fog, sailors tie their boats to the quay by listening for a low note said to come from beneath the mud."
    }
  ],
  "factions": [
    {
      "id": "fac_parish_wardens",
      "name": "The Parish Wardens",
      "description": "Keepers of the city's bell schedule and civic order. They have commanded that all bells be muffled until the coming fog passes, and they refuse to explain why.",
      "location_ids": [
        "loc_parish_tower",
        "loc_lantern_quay"
      ]
    },
    {
      "id": "fac_founders_guild",
      "name": "The Founders' Guild",
      "description": "A guarded fellowship of metalworkers who control bell molds, alloy recipes, and apprenticeships. Guild elders claim the strange pattern cannot have come from any bell they made.",
      "location_ids": [
        "loc_bellfoundry",
        "loc_drowned_market"
      ]
    },
    {
      "id": "fac_silt_clerks",
      "name": "The Silt Clerks",
      "description": "Archivists and flood surveyors who quietly compare old records against the shifting waterline. They suspect the forbidden pattern matches a sequence removed from the city's earliest ledgers.",
      "location_ids": [
        "loc_tide_archive",
        "loc_lantern_quay"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tide_memory",
      "statement": "A bell rung above the estuary leaves a faint answering vibration in submerged stone until the next low tide.",
      "category": "metaphysics"
    },
    {
      "id": "rul_casting_limits",
      "statement": "A bell's voice is set by its metal, shape, and casting; no later tuning can make it speak a wholly different note.",
      "category": "physics"
