response.output:
{
  "world_id": "wld_ninth_stall",
  "name": "The Ninth-Stall Fairlands",
  "description": "In the Fairlands, a travelling fair arrives only during leap-season, its striped lanes appearing between familiar hedgerows as if set down by careful hands. A hedge-witch tea merchant follows its route to reclaim her family's lost ninth stall, a place whose brass kettle still hangs above an empty counter. The fair is gentle but never idle: its paths rearrange at dusk, its traders keep exact accounts, and every claim must be settled through a bargain, a contest, or an exchange. Before the last lantern is lowered, she must discover what her family once promised and decide what the stall should offer next.",
  "locations": [
    {
      "id": "loc_thimblecross",
      "name": "Thimblecross Green",
      "description": "A quiet crossroads town edged with hawthorn hedges. When leap-season nears, its residents hang little cups from the branches to invite the fair's first lanterns."
    },
    {
      "id": "loc_foldway",
      "name": "The Foldway Lanes",
      "description": "The fair's shifting heart: ribbon-bright alleys that rearrange whenever the evening bell rings. A lane remembers the sound of a promise, so a tune can guide a visitor back to a place that has moved."
    },
    {
      "id": "loc_ninthstall",
      "name": "The Ninth Stall",
      "description": "An empty tea counter beneath a copper awning, marked by nine tiny kettle hooks. Its old brass sign bears the merchant family's curling leaf, but the fair's ledger lists the stall as unclaimed."
    },
    {
      "id": "loc_mooncup_orchard",
      "name": "Mooncup Orchard",
      "description": "A small orchard beyond the last lane, where pale cup-shaped blossoms collect dew that tastes faintly of whatever tea a visitor misses most. The fair's closing bell can be heard here before it rings."
    }
  ],
  "factions": [
    {
      "id": "fac_foldkeepers",
      "name": "The Foldkeepers",
      "description": "Lantern tenders and lane-minders who guide the fair between places. They protect the old ledger and insist every stall claim be settled before the lanes fold away.",
      "location_ids": [
        "loc_foldway",
        "loc_ninthstall"
      ]
    },
    {
      "id": "fac_cupwrights",
      "name": "The Cupwright Circle",
      "description": "Potters, tea blenders, and small-trade vendors who share equipment and teach newcomers their crafts. They hope to turn the empty ninth stall into a public tasting counter.",
      "location_ids": [
        "loc_thimblecross",
        "loc_ninthstall"
      ]
    },
    {
      "id": "fac_hedgekin",
      "name": "The Hedgekin Table",
      "description": "A loose fellowship of hedge-witches and growers who trade remedies, recipes, and seasonal leaves. They know the merchant family's tea traditions and the old tune that finds a lane again.",
      "location_ids": [
        "loc_thimblecross",
        "loc_mooncup_orchard"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_leapseason",
      "statement": "The travelling fair appears only in leap-season, and its lanes vanish when the final closing bell sounds.",
      "category": "metaphysics"
    },
    {
      "id": "rul_lane_memory",
      "statement": "A fair lane remembers a promise spoken within it; humming the promise's tune can reveal that lane again before closing.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bargains",
      "statement": "Claims over stalls are resolved through bargains, contests, or trade, with the terms recorded in the fair's ledger.",
      "category": "social"
    },
    {
      "id": "rul_tea",
      "statement": "Hedge-witch tea can bring forward a comforting memory, but it cannot change what happened or make a promise for the drinker.",
      "category": "metaphysics"
    },
    {
      "id": "rul_closing",
      "statement": "A stall left unsettled when the closing bell rings remains empty until the fair returns in another leap-season.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_kettle",
      "name": "The First Kettle Welcome",
      "description": "Long ago, the first Foldkeepers invited a hedge-witch tea seller to brew for weary fairgoers. Her ninth counter became a customary place to exchange a cup for a story.",
      "era": "The Fair's First Season",
      "location_ids": [
        "loc_foldway",
        "loc_ninthstall"
      ]
    },
    {
      "id": "evt_stall_promise",
      "name": "The Leafmark Promise",
      "description": "A merchant of the hedge-witch's family lent the ninth stall's brass kettle to the Foldkeepers in return for keeping the counter in the family. The promise was entered in a ledger, but its final line faded after the fair departed.",
      "era": "The Season of Copper Leaves",
      "location_ids": [
        "loc_ninthstall"
      ]
    },
    {
      "id": "evt_empty_counter",
      "name": "The Unclaimed Counter",
      "description": "When the fair next arrived, the ledger showed no settled claim to the ninth stall. The family left its sign in place, and the Cupwright Circle began tending the counter between visits.",
      "era": "The Long Interval",
      "location_ids": [
        "loc_ninthstall",
        "loc_thimblecross"
      ]
    },
    {
      "id": "evt_orchard_tune",
      "name": "The Tune in the Blossoms",
      "description": "A Hedgekin grower heard the old lane-finding tune in the wind through the Mooncup blossoms. Since then, the fellowship has kept the melody alive in case the lost ledger line can be found.",
      "era": "The Last Leap-Season",
      "location_ids": [
        "loc_mooncup_orchard",
        "loc_foldway"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_ninth_claim",
      "name": "Who May Brew at Nine",
      "description": "The returning tea merchant seeks the family counter, while the Cupwright Circle wants it opened for shared tastings. The Foldkeepers will honor the old claim only if someone can uncover the missing promise and settle the matter by the fair's closing bell.",
      "faction_ids": [
        "fac_foldkeepers",
        "fac_cupwrights",
        "fac_hedgekin"
      ]
    },
    {
      "id": "cnf_ledger_terms",
      "name": "The Missing Final Line",
      "description": "The Foldkeepers read the faded ledger as a conditional claim, while the Hedgekin Table remembers a promise of shared use. Reconstructing the terms may require a trade of rare tea leaves, a tasting contest, and a choice about whether the counter belongs to one family or the whole fair.",
      "faction_ids": [
        "fac_foldkeepers",
        "fac_hedgekin",
        "fac_cupwrights"
      ]
    }
  ]
}

