{
  "world_id": "wld_ice_and_coin",
  "name": "The Gilt Tail",
  "description": "A nomad market has been carved into the heart of a captured comet, where its icy galleries shelter a fleet of traders, privateers, pilgrims, and people with nowhere else to go. The comet is drawing toward perihelion: the coming solar burn will boil its outer ice and scatter the fleet unless the ships can catch favorable currents and hold fast. They travel by sail, tether, and reaction plume, while disputes are settled with contracts, nerve, and steel. At the center of the market, a sealed star-map has vanished. A guild factotum must decide who took it, what its seal protects, and whether justice can be done before the fleet breaks apart. One local custom gives every transaction a witness: merchants scratch their promises into thin comet-glass, whose shifting frost reveals tampering when warmed. The evidence is useful, but the warmth of the approaching sun is making every old record harder to trust.",
  "locations": [
    {
      "id": "loc_crown_market",
      "name": "Crown of Stalls",
      "description": "A vaulted bazaar spiraling around the comet's broadest cavern. Canvas awnings, brass bells, and tethered shop-boats crowd its lanes; every stall keeps a shard of comet-glass for recording bargains."
    },
    {
      "id": "loc_seal_vault",
      "name": "The Seal Vault",
      "description": "A cold chamber behind the old mining lifts, guarded by a pressure door and a chartered watch. The missing star-map was kept here, locked beneath a seal said to open only in the hands of its rightful keeper."
    },
    {
      "id": "loc_sunward_ridge",
      "name": "Sunward Ridge",
      "description": "The comet's exposed spine, braced with tether posts and sail masts. As the sun draws near, volatile ice vents here in brief, violent plumes that can propel a ship or tear its rigging apart."
    },
    {
      "id": "loc_bellows_dock",
      "name": "Bellows Dock",
      "description": "A cavernous harbor where ships moor nose to tail and crews trade sailcloth, pressure tanks, and gossip. Its docking lines are old enough that no captain trusts a single knot."
    },
    {
      "id": "loc_glass_choir",
      "name": "Glass Choir",
      "description": "A maze of ice tubes that hum when passing ships tighten their tethers. The changing notes carry through the comet, making it a place for secret meetings—and an accidental alarm system."
    }
  ],
  "factions": [
    {
      "id": "fac_counters_guild",
      "name": "The Counters' Guild",
      "description": "Market clerks, brokers, and arbitrators who keep the trade rolls and appoint the factotum charged with settling the map theft. Their authority rests on impartial ledgers, though their members disagree on whether the fleet's survival outranks strict procedure.",
      "location_ids": [
        "loc_crown_market",
        "loc_seal_vault"
      ]
    },
    {
      "id": "fac_tether_captains",
      "name": "The Tether Captains",
      "description": "A loose league of shipmasters who maintain the harbor lines and decide which vessels receive safe mooring during the burn. They prize practical seamanship, and some want the map kept secret until their ships are clear.",
      "location_ids": [
        "loc_bellows_dock",
        "loc_sunward_ridge"
      ]
    },
    {
      "id": "fac_glasskeepers",
      "name": "The Glasskeepers",
      "description": "Record-keepers and craftspeople who cut comet-glass witness shards and teach the market's bargain customs. They fear that the warming ice will erase proof of old claims, but have never agreed who may read the star-map.",
      "location_ids": [
        "loc_glass_choir",
        "loc_crown_market"
      ]
    },
    {
      "id": "fac_sable_wake",
      "name": "The Sable Wake",
      "description": "A daring flotilla of sail-runners who escort small craft through dangerous routes. Their crews insist the map could guide the whole market to a safer passage, while their rivals suspect they would sell that advantage to the highest bidder.",
      "location_ids": [
        "loc_bellows_dock",
        "loc_sunward_ridge"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_sail_and_plume",
      "statement": "Ships manoeuvre by sail, tether, and reaction plume; no energy weapons are used.",
      "category": "technology"
    },
    {
      "id": "rul_ice_thaws",
      "statement": "The comet sheds ice and releases volatile plumes as it nears the sun, making exposed routes increasingly dangerous.",
      "category": "physics"
    },
    {
      "id": "rul_frost_witness",
      "statement": "Comet-glass records reveal signs of tampering when warmed, but prolonged heat blurs their fine marks.",
      "category": "other"
    },
    {
      "id": "rul_market_charter",
      "statement": "A guild arbitrator may hear a theft claim only after both sides name a witness and submit their recorded bargains for inspection.",
      "category": "social"
    },
    {
      "id": "rul_shared_tethers",
      "statement": "Harbor tethers are held in common by charter; cutting another vessel's line without consent is an offense against the whole market.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_comet_capture",
      "name": "The Catching",
      "description": "Years ago, a band of haulers anchored their ships to the comet and used its venting ice to alter its course. They meant to harvest it briefly; instead, their families and cargoes became the first market.",
      "era": "Founding years",
      "location_ids": [
        "loc_sunward_ridge",
        "loc_bellows_dock"
      ]
    },
    {
      "id": "evt_charter_signed",
      "name": "The Charter of Common Lines",
      "description": "After a dispute over severed moorings nearly sent three ships adrift, captains and merchants declared the harbor tethers a shared trust and gave the Counters' Guild power to arbitrate claims.",
      "era": "First market season",
      "location_ids": [
        "loc_crown_market",
        "loc_bellows_dock"
      ]
    },
    {
      "id": "evt_glass_custom",
      "name": "The First Witness Shards",
      "description": "Glasskeepers found that bargains scratched into thin comet-glass changed appearance when warmed. The market adopted the shards as witnesses, turning a craft discovery into a custom that binds even the proudest captain.",
      "era": "The charter era",
      "location_ids": [
        "loc_glass_choir",
        "loc_crown_market"
      ]
    },
    {
      "id": "evt_map_sealed",
      "name": "A Map Without a Claim",
      "description": "A navigator's star-map was placed in the Seal Vault after its routes became the subject of rival claims. No faction could prove sole ownership, so the guild sealed it until a lawful keeper could be named.",
      "era": "Three market seasons ago",
      "location_ids": [
        "loc_seal_vault"
      ]
    },
    {
      "id": "evt_map_stolen",
      "name": "The Empty Vault",
      "description": "The map disappeared as the comet began its approach to the sun. The vault seal was found apparently intact, and traces of frost on nearby witness shards have begun to fade.",
      "era": "Present approach",
      "location_ids": [
        "loc_seal_vault",
        "loc_glass_choir"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_map_claims",
      "name": "Who Owns a Way Out?",
      "description": "The Sable Wake says the map must guide the whole fleet to safety; the Tether Captains fear that sharing its route will jam the few reliable passages. The Counters' Guild must judge competing claims while every delay narrows the time to leave.",
      "faction_ids": [
        "fac_sable_wake",
        "fac_tether_captains",
        "fac_counters_guild"
      ]
    },
    {
      "id": "cnf_fading_proof",
      "name": "The Warm Witness",
      "description": "The Glasskeepers can test the shards, but the comet's growing heat is erasing their clearest marks. The Guild wants a verdict before the evidence blurs; the Glasskeepers will not certify a reading they cannot defend.",
      "faction_ids": [
        "fac_glasskeepers",
        "fac_counters_guild"
      ]
    },
    {
      "id": "cnf_burn_departure",
      "name": "The Last Moorings",
      "description": "The Tether Captains control access to safe lines as the burn approaches. The Sable Wake is ready to cast off without a ruling, while the Guild insists that abandoning the hearing could leave the market's next theft beyond any law.",
      "faction_ids": [
        "fac_tether_captains",
        "fac_sable_wake",
        "fac_counters_guild"
      ]
    }
  ]
}

response.output:
{
  "world_id": "wld_saffron_soundings",
  "name": "The Saffron Soundings",
  "description": "In the Indian Ocean port of Velan, monsoon winds govern the season's narrow passage between laden ships and the open sea. Before the wind shifts, a harbour scribe must reconcile three foreign envoys' rival claims to the first sailing slot, each backed by contracts, gifts, and the threat of withheld trade. Velan's sumptuous Rain Court, crowded quays, and rain-darkened warehouses hold the pressure of a city whose prosperity depends on appearing impartial. Its most unusual instrument of law is the saffron tide-cloth: each dawn, pilots mark the harbor's soundings on a long strip of dyed cotton, and the cloth is cut into witnessed portions that record who had lawful passage as the channels alter. A missing portion could change the season's account—and the balance of power across the port.",
  "locations": [
    {
      "id": "loc_velan_quay",
      "name": "Velan's Outer Quay",
      "description": "A crescent of stone piers and timber stages where ocean-going vessels wait for pilots. Monsoon squalls drive spray across the mooring posts, and the first sailing slot is measured here by tide, draft, and the turning wind."
    },
    {
      "id": "loc_rain_court",
      "name": "The Rain Court",
      "description": "A pillared customs hall shaded by carved timber screens. Its scribe benches sit above a rain cistern, where officials hear cargo disputes and stamp contracts before merchants can claim a place in the harbor's order."
    },
    {
      "id": "loc_soundings_house",
      "name": "House of Soundings",
      "description": "A low, salt-streaked tower at the mouth of the channel, occupied by pilots who chart shifting sandbars. Saffron tide-cloth hangs from its rafters, each strip carrying witnessed marks for the depths and passages of a particular dawn."
    },
    {
      "id": "loc_cinnamon_warehouse",
      "name": "The Cinnamon Steps",
      "description": "A steep lane of bonded warehouses leading from the quay to the inland market. Pepper, indigo, and cinnamon scent the damp air; locked counting rooms shelter cargo whose owners may lose a season if their ships miss the favorable wind."
    }
  ],
  "factions": [
    {
      "id": "fac_velan_customs",
      "name": "The Rain Court Clerks",
      "description": "A hereditary office of local record-keepers responsible for contracts, harbor dues, and the official sailing order. Their authority rests on keeping the same account legible to merchants from many shores.",
      "location_ids": [
        "loc_rain_court",
        "loc_velan_quay"
      ]
    },
    {
      "id": "fac_channel_pilots",
      "name": "The Sounding Pilots",
      "description": "A close-knit guild that reads the channel's shifting shoals and makes the daily tide-cloth. They insist that safe passage depends on current measurements, not precedence bought with gifts.",
      "location_ids": [
        "loc_soundings_house",
        "loc_velan_quay"
      ]
    },
    {
      "id": "fac_western_envoys",
      "name": "The Red Sea Envoys",
      "description": "Delegates for a western fleet carrying horses, glass, and silver. Their captain claims an old priority granted after a storm-season rescue, but the original witness seal is disputed.",
      "location_ids": [
        "loc_rain_court",
        "loc_cinnamon_warehouse"
      ]
    },
    {
      "id": "fac_eastern_envoys",
      "name": "The Eastern Sea Envoys",
      "description": "Representatives of an eastern merchant fleet laden with ceramics and fine cloth. They cite a paid harbor bond and argue that a confirmed payment outranks a promise made in a former season.",
      "location_ids": [
        "loc_rain_court",
        "loc_cinnamon_warehouse"
      ]
    },
    {
      "id": "fac_island_envoys",
      "name": "The Island Envoys",
      "description": "Agents for a fleet of island traders bearing cloves and nutmeg. They claim the first slot under a pact of mutual rescue, and threaten to divert their ships if Velan treats that pact as mere courtesy.",
      "location_ids": [
        "loc_velan_quay",
        "loc_cinnamon_warehouse"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_sailing_window",
      "statement": "The monsoon reverses its prevailing wind with the season, and deep-draft ships must depart before the turn to make the long crossing safely.",
      "category": "physics"
    },
    {
      "id": "rul_pilot_soundings",
      "statement": "Only a licensed pilot may certify a ship's passage through the shifting channel; a written claim cannot make an unsafe depth navigable.",
      "category": "social"
    },
    {
      "id": "rul_tide_cloth",
      "statement": "The Rain Court recognizes a tide-cloth entry only when the pilot's mark and two witnesses' seals remain together on the same portion.",
      "category": "social"
    },
    {
      "id": "rul_harbor_records",
      "statement": "Velan's harbor works by ink, seals, messengers, and witnessed speech; no device carries messages across distance without a human bearer.",
      "category": "technology"
    },
    {
      "id": "rul_customs_neutrality",
      "statement": "A clerk who accepts an unrecorded gift from a claimant forfeits the right to determine that claimant's place in the sailing order.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_storm_rescue",
      "name": "The Night of Three Anchors",
      "description": "During a violent squall, a western captain cut loose his own anchor cable to tow two stranded vessels clear of the shoals. A Rain Court predecessor promised his fleet first passage in a later season, but the surviving account names no date or witness seals.",
      "era": "Several generations before the present season",
      "location_ids": [
        "loc_velan_quay",
        "loc_soundings_house"
      ]
    },
    {
      "id": "evt_bond_custom",
      "name": "The Bond Before Departure",
      "description": "After a merchant convoy departed without paying its dues, the port required foreign fleets to lodge a bond before receiving a sailing place. The eastern envoys' payment is genuine, though the custom never established whether payment grants priority.",
      "era": "Within living memory",
      "location_ids": [
        "loc_rain_court",
        "loc_cinnamon_warehouse"
      ]
    },
    {
      "id": "evt_cloth_pact",
      "name": "The Pact of Shared Water",
      "description": "Island traders and Velan pilots agreed to rescue one another's crews and preserve safe channel marks. The pact's language promises fair passage after a rescue, but rival interpreters disagree over whether fair means first.",
      "era": "Two decades before the present season",
      "location_ids": [
        "loc_soundings_house",
        "loc_velan_quay"
      ]
    },
    {
      "id": "evt_missing_strip",
      "name": "The Unmatched Dawn Strip",
      "description": "At the start of the present season, a portion of the saffron tide-cloth vanished between the pilot tower and the Rain Court. Its missing marks may show that one envoy's ship already received a trial passage—or that the channel was too shallow for any fleet.",
      "era": "The present monsoon",
      "location_ids": [
        "loc_soundings_house",
        "loc_rain_court"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_first_sailing_slot",
      "name": "Three Claims to One Passage",
      "description": "The western fleet invokes an ancestral rescue promise, the eastern fleet invokes its paid bond, and the island traders invoke their shared-water pact. The harbor has room for only one first departure before the wind turns; whichever claim the scribe records will shape Velan's trade and credibility for years.",
      "faction_ids": [
        "fac_western_envoys",
        "fac_eastern_envoys",
        "fac_island_envoys",
        "fac_velan_customs"
      ]
    },
    {
      "id": "cnf_missing_measure",
      "name": "The Vanished Tide-Cloth",
      "description": "The pilots refuse to certify the disputed channel without the missing dawn strip, while the envoys accuse one another of altering the record. The clerks must decide whether to delay all ships, accept sworn testimony, or risk sending a vessel through unverified water.",
      "faction_ids": [
        "fac_channel_pilots",
        "fac_western_envoys",
        "fac_eastern_envoys",
        "fac_island_envoys",
        "fac_velan_customs"
      ]
    }
  ]
}

