response.output:
{
  "world_id": "wld_wickmere_parish",
  "name": "The Wickmere Reach",
  "description": "Wickmere is a remote parish of peat moor, black pools, and scattered stone dwellings, where a new lamplighter inherits a duty older than anyone can explain. Each night the wall lanterns must remain alight in sequence; if every flame fails before dawn, something crosses the parish boundary and leaves the land subtly altered. The parish ledger records each lit night, but a page from last winter has been cut away. Its absence has become more dangerous than any written warning: the surviving entries show that the missing nights cluster around a stretch of unusually mild weather, and no one agrees who held the lamp then. In this folk-horror country, custom is treated as shelter, memory is contested, and even a steady flame may reveal a shadow with no body.",
  "locations": [
    {
      "id": "loc_wickmere_wall",
      "name": "The Lantern Wall",
      "description": "A low, ancient wall of dark stone curves around the parish's inhabited ground. Iron brackets hold the wall lanterns at uneven intervals, each marked with a small notch whose meaning the lamplighter is expected to learn by use."
    },
    {
      "id": "loc_parish_house",
      "name": "Parish House",
      "description": "A damp, steep-roofed house beside the wall, serving as vestry, storehouse, and keeper's quarters. The yearly ledger rests in a locked oak chest, and its missing leaf has left a clean, pale seam between the remaining pages."
    },
    {
      "id": "loc_siltmere",
      "name": "Siltmere Pool",
      "description": "A peat-dark pool beyond the eastern wall, ringed by reeds that never bend with the wind. On still nights it reflects the lantern line in the wrong order, as though another wall stands beneath the water."
    },
    {
      "id": "loc_bellwether_rise",
      "name": "Bellwether Rise",
      "description": "A wind-scoured rise above the western track, crowned by a leaning bell frame with no bell. From here the last lantern can be seen, but the path down sometimes returns a walker to the rise without crossing their own footprints."
    }
  ],
  "factions": [
    {
      "id": "fac_lampwardens",
      "name": "The Lampwardens",
      "description": "A small succession of parish keepers charged with trimming wicks, tending oil, and recording every night's lights. They insist the routine is practical, yet each keeper inherits a private list of lanterns never to approach alone.",
      "location_ids": [
        "loc_wickmere_wall",
        "loc_parish_house"
      ]
    },
    {
      "id": "fac_moorholders",
      "name": "The Moorholders",
      "description": "Families who graze animals and cut peat on the parish edge. They want the wall maintained but resent the keepers' authority over routes, and some quietly move boundary stones when the lights make the moor seem to shift.",
      "location_ids": [
        "loc_siltmere",
        "loc_bellwether_rise"
      ]
    },
    {
      "id": "fac_bellless_fold",
      "name": "The Bellless Fold",
      "description": "A discreet fellowship of parish elders who preserve oral accounts omitted from official records. They claim the missing ledger leaf was removed to protect a living person, and will not say whether that person is the new lamplighter.",
      "location_ids": [
        "loc_parish_house",
        "loc_bellwether_rise"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_lights_in_sequence",
      "statement": "Before dawn, at least one wall lantern must remain lit; a night in which every flame fails is followed by a breach in the parish boundary.",
      "category": "metaphysics"
    },
    {
      "id": "rul_wick_marks",
      "statement": "The notches on each lantern bracket record the order in which its wick must be trimmed; reversing that order makes the flame burn blue and gives no warmth.",
      "category": "other"
    },
    {
      "id": "rul_no_echo_at_pool",
      "statement": "A spoken name beside Siltmere Pool is echoed once by the water, unless the named person is already reflected there.",
      "category": "metaphysics"
    },
    {
      "id": "rul_parish_craft",
      "statement": "Travel, labor, and communication rely on footpaths, animal strength, hand tools, and written or spoken messages; no engines are known in the parish.",
      "category": "technology"
    },
    {
      "id": "rul_ledger_oath",
      "statement": "A keeper must enter the state of every wall lantern before sunrise, even when the entry contradicts what the keeper remembers seeing.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_wall",
      "name": "The Wall Was Raised",
      "description": "Parish tradition says the first inhabitants built the curved wall after finding their sheep penned at dawn in a place none had entered. The oldest stone bears a shallow groove shaped like a wick, though no account explains who carved it.",
      "era": "Before the parish rolls",
      "location_ids": [
        "loc_wickmere_wall"
      ]
    },
    {
      "id": "evt_pool_reflection",
      "name": "The Wrong Reflection",
      "description": "A keeper's account describes seeing the wall lanterns reflected in reverse order at Siltmere. The next morning, one bracket stood empty though its lantern had been logged as burning.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_siltmere",
        "loc_wickmere_wall"
      ]
    },
    {
      "id": "evt_mild_winter",
      "name": "Winter Without Frost",
      "description": "Last winter brought soft rain instead of hard frost. The ledger records a run of nights when the lanterns stayed lit, but one page covering the middle of the season was cut cleanly from the binding.",
      "era": "Last winter",
      "location_ids": [
        "loc_parish_house"
      ]
    },
    {
      "id": "evt_bellless_night",
      "name": "The Bell That Did Not Ring",
      "description": "During the mild winter, several residents gathered at Bellwether Rise after seeing a light moving beyond the wall. The empty bell frame swayed in still air, and by morning one witness had forgotten the name of their own child.",
      "era": "Last winter",
      "location_ids": [
        "loc_bellwether_rise"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_missing_leaf",
      "name": "The Missing Leaf",
      "description": "The Lampwardens need the ledger to keep their rounds trustworthy, while the Bellless Fold believes the absent page conceals a person whose name must not be spoken. The new keeper must decide whether to restore the record, expose the removal, or preserve the silence.",
      "faction_ids": [
        "fac_lampwardens",
        "fac_bellless_fold"
      ]
    },
    {
      "id": "cnf_boundary_claim",
      "name": "The Moving Boundary",
      "description": "The Moorholders want to reclaim grazing ground near the pool, but the Lampwardens warn that shifting the wall's lantern line could leave a stretch unguarded. Each side suspects the other is using the strange reflections to justify its own claim.",
      "faction_ids": [
        "fac_moorholders",
        "fac_lampwardens"
      ]
    }
  ]
}

